<script setup lang="ts">
import { ref,onMounted,computed } from 'vue'
import { Plus,ArrowUpRight,ArrowRight,FileText,Users,Wallet } from 'lucide-vue-next'
import { useDashboard } from '../stores/dashboard'
import { useAuth } from '../stores/auth'
import { formatNaira } from '../utils/formatNaira'
import { formatDate } from '../utils/formatDate'
import StatCard from '../components/StatCard.vue'
import StatusBadge from '../components/StatusBadge.vue'
const store=useDashboard(),auth=useAuth(),error=ref(''),loading=ref(true)
onMounted(async()=>{try{await store.load()}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
const paidRatio=computed(()=>store.data?.billed_kobo?Math.min(100,Math.round(store.data.paid_kobo/store.data.billed_kobo*100)):0)
const labels:Record<string,string>={draft:'Draft',sent:'Awaiting payment',partially_paid:'Partially paid',paid:'Paid',overdue:'Overdue',void:'Void'}
</script>
<template><div class="page-heading"><div><span class="eyebrow">YOUR BUSINESS AT A GLANCE</span><h1>Overview<span class="heading-dot">.</span></h1><p class="muted">Welcome back, {{ auth.user?.name.split(' ')[0] }}. Here’s where things stand.</p></div><RouterLink to="/invoices/new" class="button primary"><Plus :size="18"/>Create invoice</RouterLink></div><p v-if="error" class="error">{{ error }}</p><div v-if="loading" class="loading">Bringing your numbers together…</div><template v-else-if="store.data"><div class="stats-grid"><StatCard label="Total billed" :value="store.data.billed_kobo" note="Across all issued invoices"/><StatCard label="Payments received" :value="store.data.paid_kobo" note="Money already in your business" accent="green"/><StatCard label="Outstanding" :value="store.data.outstanding_kobo" note="Waiting to come in"/><StatCard label="Overdue" :value="store.data.overdue_kobo" note="Ready for a friendly follow-up" accent="orange"/></div><div class="overview-grid"><section class="panel recent-panel"><div class="panel-heading"><div><h2>Recent invoices</h2><p class="muted">The latest from your workspace</p></div><RouterLink to="/invoices" class="text-link">View all <ArrowRight :size="15"/></RouterLink></div><div class="table-wrap"><table><thead><tr><th>Invoice / Client</th><th>Due date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="invoice in store.data.recent_invoices" :key="invoice.id"><td><RouterLink :to="'/invoices/'+invoice.id" class="table-main">{{ invoice.number }}</RouterLink><small>{{ invoice.client.name }}</small></td><td>{{ formatDate(invoice.due_date) }}</td><td class="money">{{ formatNaira(invoice.total_kobo) }}</td><td><StatusBadge :status="invoice.status"/></td><td><RouterLink :to="'/invoices/'+invoice.id" class="icon-button" aria-label="View invoice"><ArrowUpRight :size="18"/></RouterLink></td></tr><tr v-if="!store.data.recent_invoices.length"><td colspan="5" class="empty">Your first invoice belongs here. Create one to get started.</td></tr></tbody></table></div></section><section class="panel collection-panel"><span class="eyebrow">PAYMENT HEALTH</span><h2>A clearer cash flow.</h2><div class="collection-ring" :style="{'--progress':paidRatio+'%'}"><div><strong>{{ paidRatio }}<span>%</span></strong><small>collected</small></div></div><div class="collection-legend"><span><i class="legend-dot"></i>Received</span><strong>{{ formatNaira(store.data.paid_kobo) }}</strong></div><div class="collection-legend"><span><i class="legend-dot pale"></i>Outstanding</span><strong>{{ formatNaira(store.data.outstanding_kobo) }}</strong></div><p class="muted">A small follow-up can make a big difference.</p></section></div><div class="bottom-grid"><section class="panel"><div class="panel-heading"><h2>Invoice breakdown</h2><FileText :size="19" class="muted"/></div><div class="status-breakdown"><div v-for="(count,status) in store.data.status_counts" :key="status"><StatusBadge :status="String(status)"/><strong>{{ count }}</strong><div class="mini-bar"><span :class="status" :style="{width:(Number(count)/Math.max(store.data.invoices_count,1)*100)+'%'}"></span></div><small>{{ labels[status] }}</small></div><p v-if="!store.data.invoices_count" class="muted">Your invoice activity will appear here.</p></div></section><section class="next-step"><span class="eyebrow">ONE LESS THING ON YOUR LIST</span><h2>From good work<br>to getting paid.</h2><p>Your next invoice is just a few clicks away.</p><RouterLink to="/invoices/new" class="button light">Let’s create it <ArrowUpRight :size="17"/></RouterLink><div class="decorative-lines"></div></section></div><div class="workspace-footer"><span><Users :size="15"/>{{ store.data.clients_count }} clients in your workspace</span><span><Wallet :size="15"/>All amounts in Nigerian naira</span></div></template></template>